import{l as o,b as t,c as l,g as e}from"./chunks/framework.Du5_AGGE.js";const h=JSON.parse('{"title":"古代汉语","description":"","frontmatter":{"title":"古代汉语","subTitle":"修辞","author":"oasis","date":"2026-10-21T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/classical-chinese/7.md","filePath":"articles/books/classical-chinese/7.md"}'),i={name:"articles/books/classical-chinese/7.md"};function s(c,p,n,a,r,b){return t(),l("div",null,[...p[0]||(p[0]=[e('<p>胡安顺教材第十一单元讲修辞：先述研究概况，再讲常见辞格。王力通论（二十八）从阅读出发，选了稽古、引经、代称、倒置、隐喻、迂回、委婉、夸饰八种。下面按辞格写，王力的名目放在相应的格里。词里的用典见 <a href="/articles/books/classical-chinese/5.html">音韵与诗词格律</a>。这里的倒置是修辞上的倒词，语法上的宾语前置见 <a href="/articles/books/classical-chinese/4.html">语法笔记</a>。</p><h2 id="修辞学研究简况" tabindex="-1">修辞学研究简况</h2><p>古人对修辞早有议论。《周易·乾·文言》说“修辞立其诚”，孔子说“辞达而已矣”。解释《诗经》的人用赋、比、兴给写法分类，毛传在兴句下标“兴也”。刘勰《文心雕龙》有《比兴》《夸饰》《事类》《丽辞》，已经按手段讨论文章。南宋陈骙《文则》是较早的修辞学专书。</p><p>现代修辞学以陈望道《修辞学发凡》（1932）为界。他区分消极修辞和积极修辞，并把辞格建成系统。杨树达《中国修辞学》（后名《汉文文言修辞学》）专讲文言。王力在通论里不求全，只讲读古书时容易按字面理解错的几种。胡安顺列出十三种常见辞格，教材还涉及口语修辞和体态语。</p><p>读古书要分清两件事：作者是在字面意义上说，还是在用一种格。下面各格都是后一种。</p><h2 id="起兴" tabindex="-1">起兴</h2><p>先说别的事物，引出要说的人或事，叫起兴。兴句在前，所咏在后。</p><blockquote><p>关关雎鸠，在河之洲。窈窕淑女，君子好逑。（《关雎》） 桃之夭夭，灼灼其华。之子于归，宜其室家。（《桃夭》）</p></blockquote><p>兴和后文的关系有紧有松。有的只借来起韵，有的兼有比喻。毛传只标“兴也”，不把比、兴拆开。朱熹《诗集传》才逐章标明赋、比、兴。看到毛传的“兴也”，不要把兴句当成叙事的正文。</p><h2 id="比喻" tabindex="-1">比喻</h2><p>比喻用另一事物说明这一事物。阅读上要分清三等：</p><ol><li><p><strong>明喻</strong>有喻词：如、若、犹、似、譬若、譬如。</p><blockquote><p>君子之交淡若水，小人之交甘若醴。（《庄子·山木》）</p></blockquote></li><li><p><strong>隐喻</strong>（王力叫隐喻，也叫暗喻）不出喻词，用“为”“是”或并置把本体和喻体接在一起。</p><blockquote><p>君者，舟也；庶人者，水也。（《荀子·王制》）</p></blockquote></li><li><p><strong>借喻</strong>连本体也不出现，直接说喻体。</p><blockquote><p>当涂者升青云，失路者委沟渠。（扬雄《解嘲》）</p></blockquote></li></ol><p>“青云”是高位，“当涂”是得志，“失路”是失志。王力强调：隐喻和借喻没有“如”“若”，最容易坐实。鸱枭、凤凰、泾渭、沟渠，都要按比喻义读，不能当成真的鸟、真的水和真的掉进沟里。</p><h2 id="夸张" tabindex="-1">夸张</h2><p>夸张是把事物说到极点，让印象加深。王力叫做<strong>夸饰</strong>，并把它和没有根据的夸大分开：夸饰是极度形容，数字和比喻都不按字面坐实。</p><blockquote><p>人固有一死，或重于泰山，或轻于鸿毛。（司马迁《报任安书》） 明星荧荧，开妆镜也；绿云扰扰，梳晓鬟也。（杜牧《阿房宫赋》）</p></blockquote><p>泰山、鸿毛是轻重的极点；妆镜不是星，头发不是云。专名也可以当极点来用：仲尼、墨翟代表最贤，陶朱、猗顿代表最富，随侯珠、和氏璧代表最贵。贾谊说秦“非有仲尼、墨翟之贤”，是说没有那样的贤才，不是在点两个人的名。</p><h2 id="引用" tabindex="-1">引用</h2><p>引用是把现成的事或话拿来支撑自己的意思。王力分成两路。</p><p><strong>稽古</strong>是叙述古人的事迹，可正可反。</p><blockquote><p>盖文王拘而演《周易》；仲尼厄而作《春秋》；屈原放逐，乃赋《离骚》……（《报任安书》）</p></blockquote><p><strong>引经</strong>是援引圣贤的话，用来作正面的依据。先秦引的经，主要是《诗》《书》《易》。《论语》引《诗》只有两次，《孟子》二十多次，《荀子》约七十次，还有“传曰”。先秦的“传”多半是传说、故事和格言；汉代以后，“传曰”也可以指《论语》一类当时还不算经的书。汉以后引用不再限于三经，《左》《论》《老》《庄》都可以引。</p><p>引用有明有暗。明引带“诗云”“传曰”。暗引不说出处，假定读者知道。扬雄《解嘲》“或解缚而相，或释褐而傅，或倚夷门而笑”，一句一个故事。王力把这种绕开直说、靠典故表达的写法另叫做<strong>迂回</strong>，骈文里最密。读法有两步：先找出处，再看作者取这个典故的哪一面。同一个故事可以有几种讲法，要靠上下文定。</p><blockquote><p>酌贪泉而觉爽，处涸辙以犹欢。北海虽赊，扶摇可接；东隅已逝，桑榆非晚。（王勃《滕王阁序》）</p></blockquote><p>“贪泉”用吴隐之饮泉而不改操守，“涸辙”用庄子的车辙之鱼，“扶摇”用《逍遥游》，“东隅”“桑榆”用冯异“失之东隅，收之桑榆”。合起来是：穷困仍要保持节操，时机晚了还可以有作为。不查出这四个出典，字面就只是喝水、车辙、北海和太阳。</p><p>上古引《诗》允许断章取义。《荀子·劝学》引“神之听之，介尔景福”，把《诗经》里的天神讲成人的精神修养；引“其仪一兮”，把“均一”讲成“专一”。这种用法当时是允许的。读引文，先分清原义和引者的用意，两处不必相同。</p><h2 id="借代" tabindex="-1">借代</h2><p>不说人或物本身，改说和他相关的名称，叫借代。王力叫做<strong>代称</strong>。常见的有：</p><ul><li><strong>用特征代事物</strong>：“二毛”是花白头发，代老人；“黄发垂髫”代老人和小孩；“带甲”代军队。</li><li><strong>用部分代全体</strong>：“风雅”代《诗经》，“风骚”代《诗经》和《楚辞》。也可以摘一句诗里的词语代全篇，沈约称曹植的诗为“函京之作”，因为原诗有“驱马过西京”。</li><li><strong>用原料代成品</strong>：《孟子》“以铁耕”，铁代铁制农具。</li><li><strong>用具体代抽象</strong>：徽索、缧绁、刀锯代刑罚，丝竹代音乐。</li><li><strong>用地名代人</strong>：彭泽代陶渊明，临川代谢灵运，颍川代山嵚。地名其实是任所，省掉了官名。</li><li><strong>用官名代人</strong>：太史公、骠骑（霍去病）、三闾（屈原）。这是尊称。</li><li><strong>用专名代通名</strong>：俞跗、扁鹊代良医，钟子期代知音，杨得意代推荐的人。</li><li><strong>割裂</strong>：从古书里截两个字，代替原句的另一个意思。《尚书》“惟孝友于兄弟”，后人用“友于”代兄弟；“贻厥孙谋”，用“贻厥”代子孙。王力认为这种截取把词拆散了。阅读时仍要能还原原句，否则“友于”两个字没有着落。</li></ul><h2 id="变文" tabindex="-1">变文</h2><p>上下文换用同义或近义的词，避免重复，叫变文。两句各说各的意思，词换了，所指的事往往同类。</p><blockquote><p>受任于败军之际，奉命于危难之间。（诸葛亮《出师表》）</p></blockquote><p>“受任”和“奉命”、“际”和“间”互相对应，是换词，不是两件不同的事。</p><blockquote><p>燕赵之收藏，韩魏之经营，齐楚之精英，几世几年，剽掠其人。（杜牧《阿房宫赋》）</p></blockquote><p>“收藏”“经营”“精英”都指金玉珍宝。按字面把“经营”理解成经商，就把变文读破了。</p><p>变文和互文都是上下句互相照应。变文换的是词，句意各自完整；互文是各说一半，必须合起来才完整。</p><h2 id="互文" tabindex="-1">互文</h2><p>上下句各举一边，意义彼此包含，叫互文，也叫互文见义。理解时要把两边的词语加到一起。</p><blockquote><p>秦时明月汉时关。（王昌龄《出塞》）</p></blockquote><p>不是秦朝只有明月、汉朝只有关，而是秦汉时的明月和关塞。</p><blockquote><p>主人下马客在船。（白居易《琵琶行》）</p></blockquote><p>主人和客都下了马，都上了船。</p><blockquote><p>东西植松柏，左右种梧桐。（《孔雀东南飞》）</p></blockquote><p>东西左右都种了松柏和梧桐。</p><blockquote><p>烟笼寒水月笼沙。（杜牧《泊秦淮》）</p></blockquote><p>烟和月笼罩着水和沙。</p><blockquote><p>不以物喜，不以己悲。（范仲淹《岳阳楼记》）</p></blockquote><p>通常的读法是：不因为外物和个人的遭遇而或喜或悲。若只按字面，就成了“遇物只会喜、遇己只会悲”，和全文不合。</p><h2 id="并提" tabindex="-1">并提</h2><p>把两件相关的事并列在一个结构里，理解时按顺序拆开、分别搭配，叫并提，也叫合叙。不能交叉，也不能合成一件事。</p><blockquote><p>繁启蕃长于春夏，畜积收藏于秋冬。（《荀子·天论》）</p></blockquote><p>繁启在春，蕃长在夏，畜积在秋，收藏在冬。</p><blockquote><p>自非亭午夜分，不见曦月。（郦道元《水经注·江水》）</p></blockquote><p>不是正午，看不见太阳；不是半夜，看不见月亮。</p><blockquote><p>若有作奸犯科及为忠善者，宜付有司论其刑赏。（诸葛亮《出师表》）</p></blockquote><p>作奸犯科的论刑，为忠善的论赏。合成“论他们的刑和赏”，两种人就没有分别了。</p><h2 id="倒置" tabindex="-1">倒置</h2><p>为了平仄、对仗或押韵，故意把词序颠倒。辞赋、骈文里多，散文里也有。要按正常词序理解。</p><blockquote><p>心游目想（萧统《文选序》）——目游心想。 心折骨惊（江淹《别赋》）——骨折心惊。“惊”为了押韵。 泉香而酒洌（欧阳修《醉翁亭记》）——泉洌而酒香。“洌”为了和上句“肥”平仄相对。</p></blockquote><p>这是修辞上的倒词。否定句里的代词宾语前置、疑问代词宾语前置，是语法规则，见 <a href="/articles/books/classical-chinese/4.html">语法笔记</a>。</p><h2 id="委婉" tabindex="-1">委婉</h2><p>有所顾忌，把话说得曲折，叫委婉。</p><p>对君主和权贵，往往不直指。《报任安书》把冤屈说成“明主不晓”；邹阳下狱，只说“左右不明”；诸葛亮不满后主宠信宦官，只说“未尝不叹息痛恨于桓、灵”。意思在字缝里。</p><p>外交辞令是另一类。《左传》成公三年“虽遇执事，其弗敢违”，字面很恭敬，意思是：即使碰上您，也不能不打。成公十三年“寡人不佞，其不能以诸侯退矣”，是说要率领诸侯来攻。执事、寡人、不佞都是套语，真正的意图在下一折。</p><p>谦敬也是委婉。书信里讲自己用谦词，讲对方用敬词。《报任安书》的“待罪辇毂下”“厕下大夫之列”“陪外廷末议”，“待罪”等于任职，“厕”等于置身其间，“末议”等于参与议论。“牛马走”“仆”“足下”“左右”都是套语，不能按字面译成赶牛马或左右两边的人。</p><p>避讳是委婉在用字上的表现。遇当代君主的名，改字、空字或省笔画。汉高祖名邦，“邦”常改作“国”；唐太宗名世民，柳宗元“以俟夫观人风者得焉”，把“民风”写成“人风”。读到不合常例的同义换字，先想是不是避讳。</p><h2 id="顶真" tabindex="-1">顶真</h2><p>上句的末尾作下句的开头，一句顶一句，叫顶真，也叫联珠、顶针。</p><blockquote><p>人法地，地法天，天法道，道法自然。（《老子》） 归来见天子，天子坐明堂。（《木兰诗》） 军书十二卷，卷卷有爷名。（同上）</p></blockquote><p>顶真是句子衔接的方式，词义不因为重复而改变。</p><h2 id="析字" tabindex="-1">析字</h2><p>把字拆开，或按字形重新拼合，让读者从部件得出另一个意思，叫析字。</p><p>离合是常见的一种。东汉童谣“千里草，何青青。十日卜，不得生”：“千里草”合成“董”，“十日卜”合成“卓”，说的是董卓将败。</p><p>化形是按部件的会意来读字。《世说新语·捷悟》记曹娥碑背文“黄绢幼妇，外孙齑臼”。杨修的解释是：黄绢是色丝，合成“绝”；幼妇是少女，合成“妙”；外孙是女子，合成“好”；齑臼是受辛，合成“辞”。八个字读成“绝妙好辞”。</p><p>析字依赖当时的字形。用今天的简化字往回拆，往往拆不开。</p><h2 id="排比" tabindex="-1">排比</h2><p>三项或三项以上、结构相似的句子排列在一起，叫排比。两项相对是对偶，规则见 <a href="/articles/books/classical-chinese/5.html">诗律</a> 的对仗。</p><blockquote><p>源不深而望流之远，根不固而求木之长，德不厚而思国之安。（魏征《谏太宗十思疏》）</p></blockquote><p>排比一般按字面读，难点在其中某一项又用了借代或变文。过秦论“席卷天下，包举宇内，囊括四海，并吞八荒”是排比，四句意思相同，同时是变文。</p><h2 id="口语里的双关和体态" tabindex="-1">口语里的双关和体态</h2><p>文言不全是庄重的书面语。乐府、民歌和对话里有当时的口语手段。</p><p><strong>谐音双关</strong>用一个音关两件事。南朝乐府“理丝入残机，何悟不成匹”，“匹”既是布匹，也是匹配。读民歌遇到莲、丝、匹、藕，先想谐音。</p><p><strong>体态</strong>是用动作把意思做出来，史传只记下动作。《孟子》“王顾左右而言他”，齐宣王把视线转开，是躲开孟子的追问。这类句子没有比喻可还原，动作本身就是内容。</p><h2 id="参考书" tabindex="-1">参考书</h2><ul><li>王力主编《古代汉语》，中华书局（通论二十八）</li><li>胡安顺、郭芹纳主编《古代汉语》，中华书局（第十一单元：修辞）</li><li>刘勰《文心雕龙》（《比兴》《夸饰》《事类》《丽辞》）</li><li>陈望道《修辞学发凡》</li><li>杨树达《汉文文言修辞学》</li></ul>',85)])])}const k=o(i,[["render",s]]);export{h as __pageData,k as default};
